// SPDX-License-Identifier: MIT
// Prismchime Ring (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/prismchime.py (unreal-team), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "prismchime:<seed>:<difficulty>") and the only draws are randrange, so the same seed is
// the same ring as the Python game. Byte parity goes through engines/unreal/core-test/prismchime_parity.txt
// (prismchime_core_test.cpp), generated by tools/minigames/prismchime_parity.py.
//
// Rules: a ring of N chimes, each with a charge and a facing. Tapping chime i sends one pulse to each of the next
// charge[i] chimes in its facing (+1 each) and i itself gains one. A chime reaching Peal (4) peals: +PealScore,
// lights, resets to 0 and gives one charge to both neighbours; peals resolve in the order chimes filled. Every chime
// lit before the taps run out wins, with TapBonus per tap left.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <array>
#include <string>
#include <vector>

namespace daedalus { namespace prismchime {

inline const char* GameId() { return "prismchime"; }
inline const char* Title() { return "Prismchime Ring"; }

constexpr int Peal = 4, PealScore = 5, TapBonus = 3;

struct Difficulty { const char* Name; int Chimes; int Taps; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 6, 8 }, { "normal", 8, 8 }, { "hard", 10, 8 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

constexpr int MaxChimes = 16;

/**
 * Peal queue for one tap, in fill order. Every push is a charge increment that reached Peal, and a tap makes at
 * most 4 increments itself plus 2 per peal; each peal nets -2 charge, so peals <= (3N + 4) / 2 and pushes
 * <= 3N + 8 < 8N for N >= 2. Eight slots per chime is therefore a hard bound and the core never allocates
 * while playing (iteration 6).
 */
struct PealQueue
{
	std::array<int, MaxChimes * 8> Slots{};
	int Head = 0, Tail = 0;
	bool Empty() const noexcept { return Head == Tail; }
	void Push(int I) noexcept { if (Tail < static_cast<int>(Slots.size())) Slots[static_cast<size_t>(Tail++)] = I; }
	int Pop() noexcept { return Slots[static_cast<size_t>(Head++)]; }
};

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<int> Charge;     // per chime
	std::vector<int> Facing;     // +1 clockwise, -1 counter
	std::vector<bool> Lit;       // has pealed at least once
	int Taps = 0, Peals = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadChime, GameOver };

	int Chimes() const { return static_cast<int>(Charge.size()); }
	int Wrap(int I) const noexcept { const int N = Chimes(); return ((I % N) + N) % N; }
	int LitCount() const { int C = 0; for (bool L : Lit) if (L) ++C; return C; }
	bool AllLit() const { return LitCount() == Chimes(); }
	/** Game.tutorial: the first ring's teaching rows (iteration 7). */
	bool FreshRing() const { return Diff && Taps == Diff->Taps && !Over; }

	/** PrismGame.start + Game.setup. False on an unknown difficulty. Draw order: all charges, then all facings. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Chimes > MaxChimes) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		const size_t N = static_cast<size_t>(Diff->Chimes);
		Charge.assign(N, 0);
		for (int& C : Charge) C = 1 + static_cast<int>(Rng.RandRange(2));
		Facing.assign(N, 0);
		for (int& F : Facing) F = Rng.RandRange(2) ? 1 : -1;
		Lit.assign(N, false);
		Taps = Diff->Taps; Peals = 0;
		return true;
	}

	/** Game.act. `Pealed` receives this tap's peal count; `Result` the Python result text. */
	Act Tap(int I, int& Pealed, std::string& Result)
	{
		Pealed = 0;
		if (Over) return Act::GameOver;
		if (I < 0 || I >= Chimes()) return Act::BadChime;
		PealQueue Queue;
		int Cur = I;
		for (int Hop = 0, Hops = Charge[static_cast<size_t>(I)]; Hop < Hops; ++Hop)
		{
			Cur = Wrap(Cur + Facing[static_cast<size_t>(I)]);
			if (++Charge[static_cast<size_t>(Cur)] >= Peal) Queue.Push(Cur);
		}
		if (++Charge[static_cast<size_t>(I)] >= Peal) Queue.Push(I);   // the rung chime resonates
		while (!Queue.Empty())
		{
			const int J = Queue.Pop();
			if (Charge[static_cast<size_t>(J)] < Peal) continue;   // a neighbour's peal may already have drained it
			PealChime(J, Queue);
			++Pealed;
		}
		--Taps;
		const std::string Head = "tap " + std::to_string(I) + ": " + std::to_string(Pealed) + " peal(s)";
		if (AllLit())
		{
			Score += TapBonus * Taps;
			Over = Won = true;
			Result = Head + ", every chime rings";
			return Act::Ok;
		}
		if (Taps <= 0)
		{
			Over = true; Won = false;
			Result = Head + ", the ring falls silent";
			return Act::Ok;
		}
		Result = Head;
		return Act::Ok;
	}

	/** Game.preview: peals and newly lit chimes a tap on `I` would produce, leaving this game untouched (iteration 8). */
	void Preview(int I, int& Pealed, int& NewlyLit) const
	{
		Game Trial = *this;
		std::string Text;
		Pealed = 0;
		if (Trial.Tap(I, Pealed, Text) != Act::Ok) { Pealed = 0; NewlyLit = 0; return; }
		NewlyLit = Trial.LitCount() - LitCount();
	}

	/** Game.demo_action: try every chime on a copy; most newly lit, then most score, then the lowest index. */
	int DemoAction() const
	{
		int Best = 0; long long BestKey[2] = { -1, -1 };
		for (int I = 0; I < Chimes(); ++I)
		{
			Game Trial = *this;
			int Pealed = 0; std::string Text;
			Trial.Tap(I, Pealed, Text);
			const long long Key[2] = { Trial.LitCount() - LitCount(), Trial.Score - Score };
			if (Key[0] > BestKey[0] || (Key[0] == BestKey[0] && Key[1] > BestKey[1])) { BestKey[0] = Key[0]; BestKey[1] = Key[1]; Best = I; }
		}
		return Best;
	}

	std::string ChargeString() const { std::string S; for (size_t I = 0; I < Charge.size(); ++I) { if (I) S.push_back(','); S += std::to_string(Charge[I]); } return S; }
	std::string FacingString() const { std::string S; for (size_t I = 0; I < Facing.size(); ++I) { if (I) S.push_back(','); S += Facing[I] > 0 ? "+1" : "-1"; } return S; }
	std::string LitString() const { std::string S; for (bool L : Lit) S.push_back(L ? '1' : '0'); return S; }

private:
	/** Chime I peals: score, light, reset, and charge both neighbours, queueing any that fill. */
	void PealChime(int I, PealQueue& Queue) noexcept
	{
		Charge[static_cast<size_t>(I)] = 0;
		Lit[static_cast<size_t>(I)] = true;
		++Peals;
		Score += PealScore;
		for (int J : { Wrap(I - 1), Wrap(I + 1) })
			if (++Charge[static_cast<size_t>(J)] >= Peal) Queue.Push(J);
	}
};

} } // namespace daedalus::prismchime
